      IF enb = '1' THEN
        Delay1_reg(0) <= Variant_Subsystem_out5;
        Delay1_reg(7 DOWNTO 1) <= Delay1_reg(6 DOWNTO 0);
      END IF;
    END IF;
  END PROCESS Delay1_process;

  Delay1_out1 <= Delay1_reg(7);

  
  Switch1_out1 <= Convolver_out7 WHEN WrDir = '0' ELSE
      Delay1_out1;

  done <= Switch1_out1;

  WrValid_0 <= WrValid(0);

  WrValid_1 <= WrValid(1);

  WrValid_2 <= WrValid(2);

  WrValid_3 <= WrValid(3);

  WrValid_4 <= WrValid(4);

  WrValid_5 <= WrValid(5);

  WrValid_6 <= WrValid(6);

  WrValid_7 <= WrValid(7);

  Delay2_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Delay2_reg <= (OTHERS => '0');
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        Delay2_reg(8 DOWNTO 0) <= Variant_Subsystem_out1(8 DOWNTO 0);
        Delay2_reg(71 DOWNTO 9) <= Delay2_reg(62 DOWNTO 0);
      END IF;
    END IF;
  END PROCESS Delay2_process;

  Delay2_out1(8 DOWNTO 0) <= Delay2_reg(71 DOWNTO 63);

  WrValid_8 <= Delay2_out1;

  WrValid_0_1 <= WrValid_8(0);

  WrValid_1_1 <= Delay2_out1(1);

  WrValid_2_1 <= Delay2_out1(2);

  WrValid_3_1 <= Delay2_out1(3);

  WrValid_4_1 <= Delay2_out1(4);

  WrValid_5_1 <= Delay2_out1(5);

  WrValid_6_1 <= Delay2_out1(6);

  WrValid_7_1 <= Delay2_out1(7);

  WrValid_8_1 <= WrValid(8);

  Logical_Operator1_out1 <= WrValid_8_1 OR (WrValid_7 OR (WrValid_6 OR (WrValid_5 OR (WrValid_4 OR (WrValid_3 OR (WrValid_2 OR (WrValid_0 OR WrValid_1)))))));

  WrValid_8_2 <= Delay2_out1(8);

  Logical_Operator9_out1 <= WrValid_8_2 OR (WrValid_7_1 OR (WrValid_6_1 OR (WrValid_5_1 OR (WrValid_4_1 OR (WrValid_3_1 OR (WrValid_2_1 OR (WrValid_0_1 OR WrValid_1_1)))))));

  outputgen3: FOR k IN 0 TO 8 GENERATE
    Convolver_out4_unsigned(k) <= unsigned(Convolver_out4(k));
  END GENERATE;


  WrAddr_gen: FOR ii IN 0 TO 8 GENERATE
    WrAddr(ii) <= Convolver_out4_unsigned(ii)(5 DOWNTO 0);
  END GENERATE WrAddr_gen;


  outputgen2: FOR k IN 0 TO 8 GENERATE
    Bus_Creator4_out1_WrAddr(k) <= std_logic_vector(WrAddr(k));
  END GENERATE;

  outputgen1: FOR k IN 0 TO 8 GENERATE
    Variant_Subsystem_out3_unsigned(k) <= unsigned(Variant_Subsystem_out3(k));
  END GENERATE;

  Delay3_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Delay3_reg <= (OTHERS => to_unsigned(0, 32));
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        Delay3_reg(0 TO 8) <= Variant_Subsystem_out3_unsigned(0 TO 8);
        Delay3_reg(9 TO 71) <= Delay3_reg(0 TO 62);
      END IF;
    END IF;
  END PROCESS Delay3_process;

  Delay3_out1(0 TO 8) <= Delay3_reg(63 TO 71);


  WrAddr_1_gen: FOR ii1 IN 0 TO 8 GENERATE
    WrAddr_1(ii1) <= Delay3_out1(ii1)(5 DOWNTO 0);
  END GENERATE WrAddr_1_gen;


  outputgen: FOR k IN 0 TO 8 GENERATE
    Bus_Creator5_out1_WrAddr(k) <= std_logic_vector(WrAddr_1(k));
  END GENERATE;

  WrDir_1 <= memDir;

  WrBus_WrValid <= WrBusMatrix1_out1_WrValid;

  WrBus_WrDir <= WrBusMatrix1_out1_WrDir;

  Logical_Operator_out1 <=  NOT WrDir;

  RdValid <= (OTHERS => '1');

  RdValid_1 <= (OTHERS => '0');

  
  RdValid_2 <= RdValid WHEN Delay1_out1 = '0' ELSE
      RdValid_1;

  RdDir <=  NOT memDir;

  
  Compare_To_Constant_out1 <= '1' WHEN convMode_unsigned /= to_unsigned(16#02#, 8) ELSE
      '0';

  Constant6_out1 <= '0';

  
  Switch4_out1 <= Constant6_out1 WHEN Compare_To_Constant_out1 = '0' ELSE
      convStart;

  RdValid_3 <= (OTHERS => '0');

  RdValid_4 <= (OTHERS => '1');

  
  RdValid_5 <= RdValid_3 WHEN rdVal = '0' ELSE
      RdValid_4;

  WrDir_2 <= memDir;

  RdDir_1 <=  NOT WrDir_2;

  RdBus1_RdValid <= RdBusMatrix_out1_RdValid;

  RdBus1_RdDir <= RdBusMatrix_out1_RdDir;

  Convolver_out6 <= '0';

  ready <= Convolver_out6;

  RdValid_6 <= (OTHERS => '1');

  RdBus2_RdValid <= RdValid_6;

  RdDir_2 <= memDir;

  RdBus2_RdDir <= RdDir_2;

  weight_burst_start <= Convolver_out9;

  FinalTileLoading <= Convolver_out11;

  WrBus_WrData <= WrBusMatrix1_out1_WrData;

  WrBus_WrAddr <= WrBusMatrix1_out1_WrAddr;

  RdBus1_RdAddr <= RdBusMatrix_out1_RdAddr;

  RdBus2_RdAddr <= RdAddr_1;

  weight_burst_length <= Convolver_out8;

  unpoolIndexAddr <= Convolver_out10;

END rtl;

